// The Deep fixture for fractal-engine's perturbation backend: the website's committed
// `perturb-scalar.wasm` draws every parity spec and every Deep gallery link at ss 1 on a
// small fixed grid, and `engine.wasm` shades each field, so a native draw of the same spec
// can be held to the explorer's own bytes.
//
//   node make-deep-cases.mjs <fractal-website checkout> [--specs <parity-specs.jsonl>] > deep-cases.json
//
// Read-only over the website: it imports the contract modules and the committed modules
// (`bench/perturb.mjs` and `bench/engine.mjs` speak their boundary), exactly as
// builder/deep_gallery_shade.mjs does, and writes nothing there. The parity specs default to
// the kernel's own, `fractal-wallpapers/perturbation/tests/parity-specs.jsonl` in the checkout
// beside the website's; `--specs` (or a second positional argument) names another copy of
// them, and the head records which, relative to the checkout that tracks it.
//
// The kernel work is spread over at most three worker threads (the box's render-pool
// rule); the cases come out in a fixed order whatever order the workers finish in:
// the parity specs in file order, then the gallery in file order.

import { readFileSync } from "node:fs";
import { dirname, join, relative, resolve, basename } from "node:path";
import { pathToFileURL } from "node:url";
import { execFileSync } from "node:child_process";
import { Worker, isMainThread, parentPort, workerData } from "node:worker_threads";

const WORKERS = 3;

// ------------------------------------------------------------------ the worker

if (!isMainThread) {
  const { load } = await import(
    pathToFileURL(join(workerData.site, "explorer/bench/perturb.mjs")).href
  );
  const P = await load(pathToFileURL(join(workerData.site, "explorer/perturb-scalar.wasm")));
  parentPort.on("message", ({ index, spec }) => {
    const started = performance.now();
    const lanes = P.frame(spec); // the reference, then compute_band over every row at once
    const ran = P.wasm.band_ran();
    const saved = P.wasm.band_saved();
    const seconds = (performance.now() - started) / 1000;
    parentPort.postMessage({ index, lanes, ran, saved, seconds }, [lanes.buffer]);
  });
} else {
  await main();
}

// ------------------------------------------------------------------ the main thread

async function main() {
  const args = process.argv.slice(2);
  let specsArg = null;
  const positional = [];
  for (let at = 0; at < args.length; at++) {
    if (args[at] === "--specs") specsArg = args[++at];
    else positional.push(args[at]);
  }
  const site = resolve(positional[0]);
  if (specsArg === null && positional[1] !== undefined) specsArg = positional[1];
  const specsPath = resolve(
    specsArg ?? join(site, "..", "fractal-wallpapers", "perturbation/tests/parity-specs.jsonl"),
  );

  const url = (path) => pathToFileURL(join(site, path)).href;
  const engineModule = await import(url("explorer/bench/engine.mjs"));
  const perturbModule = await import(url("explorer/bench/perturb.mjs"));
  const { install, stopsOf } = await import(url("explorer/stops.js"));
  const { PALETTES } = await import(url("explorer/palettes.js"));
  const { canonicalize, parse } = await import(url("explorer/deep-link.js"));
  const { deepSpecOf, shadeSpecOf } = await import(url("explorer/deep-render.js"));

  install(new Uint8Array(readFileSync(join(site, "explorer/palettes.bin"))));
  let E = await engineModule.load(pathToFileURL(join(site, "explorer/engine.wasm")));
  const P = await perturbModule.load(pathToFileURL(join(site, "explorer/perturb-scalar.wasm")));

  // builder/deep_gallery_shade.mjs's context, with the width cap the module itself gives: a
  // link carrying `n` never asks for it, and every gallery row carries one.
  const context = {
    palettes: PALETTES,
    defaultPalette: "glowdon",
    deepHome: () => ({ x: "-0.5", y: "0", w: "3" }),
    deepCap: (width) => P.maxiter(width),
  };

  // The parity specs carry no colour, so one constant link supplies the shade every parity
  // field is coloured by: Absolute, so nothing is fitted, and a palette the library holds.
  const SHADE_LINK = "dv=3&x=0&y=0&w=1&n=100&p=viridis&scale=absolute&period=40";
  if (canonicalize(SHADE_LINK, context) !== SHADE_LINK) throw new Error("SHADE_LINK is not canonical");
  const shadeView = parse(SHADE_LINK, context);
  const shadeStops = stopsOf(shadeView.palette);

  // The gallery's grid: small, 16:9 like every gallery link, ss 1.
  const GRID = [32, 18];

  // ---------------------------------------------------------------- the jobs

  const jobs = [];
  const specText = readFileSync(specsPath, "utf8");
  for (const line of specText.split("\n")) {
    if (!line.trim()) continue;
    const tab = line.indexOf("\t");
    if (tab < 0) throw new Error(`parity spec line without a tab: ${line}`);
    const label = line.slice(0, tab);
    const spec = JSON.parse(line.slice(tab + 1));
    if ((spec.supersample ?? 1) !== 1) throw new Error(`${label}: parity specs are ss 1`);
    const [width, height] = spec.resolution;
    jobs.push({
      row: { source: "parity", label, spec },
      spec,
      shade: shadeSpecOf(shadeView, shadeStops, width, height),
    });
  }
  const parityCount = jobs.length;

  const galleryRows = readFileSync(join(site, "explorer/deep-gallery.jsonl"), "utf8")
    .split("\n")
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line));
  for (const [at, entry] of galleryRows.entries()) {
    const link = entry.link;
    if (canonicalize(link, context) !== link) throw new Error(`gallery ${at}: not a fixed point`);
    const view = parse(link, context);
    if (view.aspect.across * 9 !== view.aspect.down * 16) {
      throw new Error(`gallery ${at}: aspect ${view.aspect.across}:${view.aspect.down} is not 16:9`);
    }
    const spec = deepSpecOf(view, GRID[0], GRID[1]);
    const row = { source: "gallery" };
    if (entry.subject !== undefined) row.subject = entry.subject;
    row.query = link;
    row.spec = spec;
    // A link that names no `scale` is fitted on arrival, which render-link refuses.
    const scaled = new URLSearchParams(link).has("scale");
    jobs.push({
      row,
      spec,
      shade: scaled ? shadeSpecOf(view, stopsOf(view.palette), GRID[0], GRID[1]) : null,
    });
  }

  // ---------------------------------------------------------------- the draw

  const total = jobs.length;
  const results = new Array(total);
  const started = performance.now();
  let next = 0;
  let done = 0;
  let slowest = { seconds: 0, at: -1 };
  await new Promise((finish, fail) => {
    const pool = [];
    const feed = (worker) => {
      if (next >= total) {
        worker.terminate();
        return;
      }
      const index = next++;
      worker.postMessage({ index, spec: jobs[index].spec });
    };
    for (let k = 0; k < Math.min(WORKERS, total); k++) {
      const worker = new Worker(new URL(import.meta.url), { workerData: { site } });
      worker.on("message", (message) => {
        results[message.index] = message;
        done++;
        if (message.seconds > slowest.seconds) slowest = { seconds: message.seconds, at: message.index };
        const job = jobs[message.index];
        const name = job.row.label ?? job.row.subject ?? "";
        process.stderr.write(
          `[${done}/${total}] #${message.index} ${job.row.source} ${name} ` +
            `${message.seconds.toFixed(2)}s ran=${message.ran}\n`,
        );
        if (done === total) finish();
        feed(worker);
      });
      worker.on("error", fail);
      pool.push(worker);
      feed(worker);
    }
  });
  const elapsed = (performance.now() - started) / 1000;
  process.stderr.write(
    `drew ${total} cases in ${elapsed.toFixed(1)}s; slowest #${slowest.at} ${slowest.seconds.toFixed(2)}s\n`,
  );

  // ---------------------------------------------------------------- the rows

  const out = [];
  for (const [index, job] of jobs.entries()) {
    const { lanes, ran, saved } = results[index];
    const [width, height] = job.spec.resolution;
    if (lanes.length !== width * height * 8) throw new Error(`#${index}: lane length`);
    const values = new Float64Array(lanes.buffer, lanes.byteOffset, width * height);
    const mask = Uint8Array.from(values, (value) => (Number.isNaN(value) ? 1 : 0));
    const row = { ...job.row };
    row.lanes = fnv(lanes);
    row.ran = ran;
    row.saved = saved;
    row.nan = fnv(mask);
    row.values = Buffer.from(lanes.buffer, lanes.byteOffset, lanes.length).toString("base64");
    if (job.shade === null) {
      row.rgb = null;
      row.pixels = null;
      row.why = "no scale: the arrival fit";
    } else {
      let shaded;
      try {
        shaded = E.shadeLevel(job.shade, lanes, 0);
      } catch (error) {
        // A trap poisons the instance, so the next case gets a fresh one. Said in the row
        // rather than skipped: the field is still recorded and still held.
        if (!(error instanceof WebAssembly.RuntimeError)) throw error;
        E = await engineModule.load(pathToFileURL(join(site, "explorer/engine.wasm")));
        shaded = undefined;
      }
      if (shaded === null) throw new Error(`#${index}: shade_level refused`);
      if (shaded === undefined) {
        row.rgb = null;
        row.pixels = null;
        row.why = `engine.wasm shade_level traps on a ${width}x${height} field`;
        process.stderr.write(`#${index} ${job.row.label ?? ""}: ${row.why}\n`);
      } else {
        const rgb = stripAlpha(shaded.image);
        row.rgb = fnv(rgb);
        row.pixels = Buffer.from(rgb).toString("base64");
      }
    }
    out.push(row);
  }

  // ---------------------------------------------------------------- the head

  const git = (cwd, ...rest) => execFileSync("git", ["-C", cwd, ...rest], { encoding: "utf8" }).trim();
  const commit = git(site, "rev-parse", "HEAD");
  const contract = [
    "explorer/perturb-scalar.wasm",
    "explorer/engine.wasm",
    "explorer/palettes.bin",
    "explorer/palettes.js",
    "explorer/deep-link.js",
    "explorer/deep-render.js",
    "explorer/deep-fx.js",
    "explorer/stops.js",
    "explorer/deep-gallery.jsonl",
  ];
  const blobs = {};
  for (const path of contract) blobs[path] = git(site, "hash-object", "--path", path, "--", path);
  // The specs, named relative to whichever checkout tracks them. `hash-object --path`
  // hashes a file whether or not it is tracked; `status` says whether it is the committed
  // one.
  const specsRoot = git(dirname(specsPath), "rev-parse", "--show-toplevel");
  const specsRel = relative(specsRoot, specsPath).split("\\").join("/");
  if (specsRel.startsWith("..")) throw new Error(`${specsPath} is outside ${specsRoot}`);
  const specsName = `${basename(specsRoot)}:${specsRel}`;
  blobs[specsName] = git(specsRoot, "hash-object", "--path", specsRel, "--", specsRel);
  const dirty =
    git(site, "status", "--porcelain", "--", ...contract) !== "" ||
    git(specsRoot, "status", "--porcelain", "--", specsRel) !== "";

  const head = {
    schema: 1,
    what:
      "Deep frames as the explorer's CPU kernel draws them: the website's committed " +
      "perturb-scalar.wasm over every parity spec at its own grid and over every Deep gallery " +
      `link at ${GRID[0]}x${GRID[1]}, ss 1 — a parity spec as it is written, a gallery link ` +
      "at a cold open (no held reference, no period) — and " +
      "engine.wasm's shade_level colouring each field. Each case carries the spec as the " +
      "page builds it, `lanes` (FNV-1a-64 over the little-endian f64 lanes, rows in order " +
      "over the whole frame, NaN for interior), `ran`/`saved` (the band counters after that " +
      "one whole-frame call), `nan` (FNV over one byte a sample, 1 where the lane is NaN), " +
      "`values` (the lane bytes, base64), and `rgb`/`pixels` (FNV and base64 of the shaded " +
      "picture with alpha stripped). Parity specs carry no colour and are shaded by " +
      "`shade_link`; a gallery link without `scale` records `rgb: null` and `why`, as " +
      "render-link refuses it, and so would a field engine.wasm's shade_level trapped on " +
      "(none does). The Rust test parses each `spec`, draws it natively with " +
      "compute_rows, and holds `nan`, `ran` and `saved` exactly and `lanes` and `rgb` " +
      "exactly or within its stated tolerance. Regenerated by running `generator` under " +
      "node with the fractal-website checkout as its argument (and `--specs <path>` for the " +
      "parity specs); `contract_blobs` names the git blob of each file it read.",
    generated_from:
      `fractal-website ${commit}` +
      (resolve(specsRoot) === resolve(git(site, "rev-parse", "--show-toplevel"))
        ? ""
        : `, specs at ${basename(specsRoot)} ${git(specsRoot, "rev-parse", "HEAD")}`) +
      (dirty ? " with uncommitted changes" : ""),
    contract_blobs: blobs,
    specs: specsName,
    grid: GRID,
    shade_link: SHADE_LINK,
    generator: readFileSync(new URL(import.meta.url), "utf8"),
  };
  // One case a line, so a regenerated fixture diffs by the case that moved.
  const lines = Object.entries(head).map(
    ([key, value]) => ` ${JSON.stringify(key)}: ${JSON.stringify(value)},`,
  );
  process.stdout.write(
    `{\n${lines.join("\n")}\n "cases": [\n${out.map((row) => `  ${JSON.stringify(row)}`).join(",\n")}\n ]\n}\n`,
  );
  process.stderr.write(`${parityCount} parity cases, ${out.length - parityCount} gallery cases\n`);
}

// ------------------------------------------------------------------ helpers

/** FNV-1a-64 over bytes, as 16 lowercase hex digits. */
function fnv(bytes) {
  let hash = 0xcbf29ce484222325n;
  for (const byte of bytes) hash = BigInt.asUintN(64, (hash ^ BigInt(byte)) * 0x100000001b3n);
  return hash.toString(16).padStart(16, "0");
}

/** RGBA to RGB: the native shader hands out three bytes a pixel. */
function stripAlpha(rgba) {
  const rgb = new Uint8Array((rgba.length / 4) * 3);
  for (let i = 0, o = 0; i < rgba.length; i += 4, o += 3) {
    rgb[o] = rgba[i];
    rgb[o + 1] = rgba[i + 1];
    rgb[o + 2] = rgba[i + 2];
  }
  return rgb;
}
